import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt(); // 'm' is read but not used in the original code
        int[] sequence = new int[n + 1];
        sequence[0] = 0;
        sequence[1] = 1;
        long total = 1;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            long sum_value = total;

            for (int f = 2; f < limit; f++) {
                sum_value += sequence[i / f];
            }

            int boundary = i;
            int j = 1;
            while (j <= i / limit) {
                int next_b = i / (j + 1);
                sum_value += (boundary - next_b) * sequence[j];
                boundary = next_b;
                j++;
            }

            total += sum_value;
            sequence[i] = (int) sum_value;
        }

        System.out.println(sequence[n]);
        sc.close();
    }
}
